using System;
using System.Linq;
using System.Windows.Forms;
using SharpDX;
namespace CodeWalker {
 public partial class WorldForm {
  protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==Keys.F2&&!ClxnTextEntryFocused()&&!clxnFlightPlaying&&!clxnWalking){ClxnCollapse(!clxnUiCollapsed);return true;}if(keyData==(Keys.Control|Keys.Shift|Keys.T)){ClxnTheme.Toggle();return true;}if(clxnFlightPlaying&&(keyData&Keys.KeyCode)==Keys.Tab){clxnPlaybackBar.Visible=!clxnPlaybackBar.Visible;Focus();return true;}return base.ProcessCmdKey(ref msg,keyData);}
  volatile bool clxnFlightPlaying,clxnFlightPaused,clxnFlightEnded;
  ClxnCameraKey[] clxnFlightKeys=Array.Empty<ClxnCameraKey>();bool clxnFlightSmooth,clxnFlightOldAnimation;
  float clxnFlightTime,clxnFlightLength,clxnFlightOldFov;Vector3 clxnFlightOldPosition,clxnFlightOldRotation;
  void ClxnRefreshKeys(){if(clxnKeyList==null)return;int selected=clxnKeyList.SelectedIndex;clxnKeyList.Items.Clear();lock(ClxnProject.Sync)foreach(var key in ClxnProject.CameraKeys)clxnKeyList.Items.Add(key);if(clxnKeyList.Items.Count>0)clxnKeyList.SelectedIndex=Math.Max(0,Math.Min(selected,clxnKeyList.Items.Count-1));clxnSmooth.Checked=ClxnProject.SmoothFlight;}
  void ClxnCaptureKey(){if(!initialised){clxnMessage="Дождитесь загрузки карты перед добавлением кадра.";return;}if(clxnWalking||clxnFlightPlaying){clxnMessage="Завершите предпросмотр перед добавлением кадра.";return;}lock(ClxnProject.Sync)if(ClxnProject.CameraKeys.Count>=500){clxnMessage="В пролётке уже 500 кадров.";return;}ClxnProject.Checkpoint();lock(RenderSyncRoot)lock(ClxnProject.Sync)ClxnProject.CameraKeys.Add(new ClxnCameraKey{Name="Кадр "+(ClxnProject.CameraKeys.Count+1),Position=camera.Position,Rotation=camera.CurrentRotation,Fov=camera.FieldOfView});ClxnProject.Commit();ClxnRefreshKeys();clxnKeyList.SelectedIndex=clxnKeyList.Items.Count-1;clxnMessage="Кадр камеры добавлен. Переместитесь и нажмите F4 ещё раз.";}
  void ClxnShowKey(){if(!(clxnKeyList.SelectedItem is ClxnCameraKey k))return;clxnKeySeconds.Value=(decimal)k.Seconds;clxnKeyFov.Value=Math.Max(15,Math.Min(120,(decimal)(k.Fov*180/Math.PI)));}
  void ClxnReplaceKey(){var k=clxnKeyList.SelectedItem as ClxnCameraKey;if(k==null)return;ClxnProject.Checkpoint();lock(RenderSyncRoot)lock(ClxnProject.Sync){k.Position=camera.Position;k.Rotation=camera.CurrentRotation;k.Fov=camera.FieldOfView;}ClxnProject.Commit();ClxnRefreshKeys();clxnMessage="Кадр обновлён из текущей камеры.";}
  void ClxnApplyKey(){var k=clxnKeyList.SelectedItem as ClxnCameraKey;if(k==null)return;ClxnProject.Checkpoint();lock(ClxnProject.Sync){k.Seconds=(float)clxnKeySeconds.Value;k.Fov=(float)clxnKeyFov.Value*(float)Math.PI/180;}ClxnProject.Commit();ClxnRefreshKeys();clxnMessage="Время перехода и угол обзора сохранены.";}
  void ClxnMoveKey(int offset){int from=clxnKeyList.SelectedIndex,to=from+offset;lock(ClxnProject.Sync){if(from<0||to<0||to>=ClxnProject.CameraKeys.Count)return;ClxnProject.Checkpoint();var k=ClxnProject.CameraKeys[from];ClxnProject.CameraKeys.RemoveAt(from);ClxnProject.CameraKeys.Insert(to,k);}ClxnProject.Commit();ClxnRefreshKeys();clxnKeyList.SelectedIndex=to;clxnMessage="Порядок кадров изменён.";}
  void ClxnDeleteKey(){int index=clxnKeyList.SelectedIndex;if(index<0)return;ClxnProject.Checkpoint();lock(ClxnProject.Sync)ClxnProject.CameraKeys.RemoveAt(index);ClxnProject.Commit();ClxnRefreshKeys();clxnMessage="Кадр удалён.";}
  void ClxnVisitKey(){var k=clxnKeyList.SelectedItem as ClxnCameraKey;if(k==null)return;lock(RenderSyncRoot)ClxnApplyFlightCamera(k.Position,k.Rotation,k.Fov);clxnMessage="Камера перемещена к выбранному кадру.";}
  void ClxnApplyFlightCamera(Vector3 position,Vector3 rotation,float fov){camera.TargetRotation=rotation;camera.FieldOfView=fov;camera.FieldOfViewFactor=.5f/(float)Math.Tan(fov*.5f);camera.UpdateProj=true;ClxnCameraNavigation.Restore(camera,position);}
  void ClxnStartFlight(){if(clxnFlightPlaying){ClxnPauseFlight();return;}if(!initialised){clxnMessage="Дождитесь загрузки карты.";return;}if(clxnWalking)ClxnLeaveWalk();ClxnFinishStroke();lock(ClxnProject.Sync){if(ClxnProject.CameraKeys.Count<2){clxnMessage="Для пролётки нужны минимум два кадра. Добавляйте их клавишей F4.";return;}clxnFlightKeys=ClxnProject.CameraKeys.Select(k=>k.Copy()).ToArray();clxnFlightSmooth=ClxnProject.SmoothFlight;}if(MapViewEnabled)SetCameraMode("Perspective");ClxnSetTool("move");SetControlMode(WorldControlMode.Free);lock(RenderSyncRoot){clxnFlightOldPosition=camera.Position;clxnFlightOldRotation=camera.CurrentRotation;clxnFlightOldFov=camera.FieldOfView;clxnFlightOldAnimation=Renderer.timerunning;Renderer.timerunning=true;clxnFlightTime=0;clxnFlightLength=ClxnFlightMath.Duration(clxnFlightKeys);clxnFlightPaused=false;clxnFlightEnded=false;clxnFlightPlaying=true;ClxnApplyFlightCamera(clxnFlightKeys[0].Position,clxnFlightKeys[0].Rotation,clxnFlightKeys[0].Fov);}clxnWardrobe.Visible=false;if(clxnEnvironment!=null)clxnEnvironment.Visible=false;clxnHud.Visible=clxnRail.Visible=clxnOptions.Visible=clxnLibrary.Visible=clxnLogPanel.Visible=clxnFlightPanel.Visible=false;clxnPlaybackBar.Visible=true;clxnPlaybackBar.BringToFront();Focus();clxnMessage="Запущена пролётка. F5 — пауза, Esc — вернуться.";}
  void ClxnPauseFlight(){if(clxnExporting)return;if(!clxnFlightPlaying){ClxnStartFlight();return;}clxnFlightPaused=!clxnFlightPaused;if(clxnFlightPaused)clxnPlaybackBar.Visible=true;clxnMessage=clxnFlightPaused?"Пролётка приостановлена.":"Пролётка продолжена.";}
  void ClxnStopFlight(){if(clxnExporting){ClxnCancelExport();return;}if(!clxnFlightPlaying)return;lock(RenderSyncRoot){clxnFlightPlaying=false;clxnFlightPaused=false;clxnFlightEnded=false;Renderer.timerunning=clxnFlightOldAnimation;ClxnApplyFlightCamera(clxnFlightOldPosition,clxnFlightOldRotation,clxnFlightOldFov);}clxnHud.Visible=clxnRail.Visible=clxnOptions.Visible=true;clxnFlightPanel.Visible=true;clxnPlaybackBar.Visible=false;ClxnLayout();clxnMessage="Предпросмотр остановлен. Камера редактора восстановлена.";}
  void ClxnSeekFlight(float fraction){if(clxnWalking)return;ClxnCameraKey[] keys;lock(ClxnProject.Sync)keys=ClxnProject.CameraKeys.Select(k=>k.Copy()).ToArray();if(keys.Length<2)return;lock(RenderSyncRoot){float time=ClxnFlightMath.Duration(keys)*fraction;Vector3 p,r;float f;ClxnFlightMath.Evaluate(keys,time,ClxnProject.SmoothFlight,out p,out r,out f);ClxnApplyFlightCamera(p,r,f);}}
  void ClxnUpdateFlight(float elapsed){if(!clxnFlightPlaying)return;if(clxnExporting){ClxnPositionExportCamera();return;}if(!clxnFlightPaused)clxnFlightTime=Math.Min(clxnFlightLength,clxnFlightTime+Math.Max(0,elapsed));Vector3 p,r;float f;ClxnFlightMath.Evaluate(clxnFlightKeys,clxnFlightTime,clxnFlightSmooth,out p,out r,out f);ClxnApplyFlightCamera(p,r,f);if(clxnFlightTime>=clxnFlightLength)clxnFlightEnded=true;}
 }
}
